package eu.wohlben.qits.cli.bootstrap.platform;

import java.util.Collection;
import java.util.Map;

/**
 * The seed stack, generated. It is a port of the heredoc in {@code qits-local-up.sh}, comments and
 * all: the comments are where the reasons live, and a
 * generated file nobody can read is a file nobody can fix.
 * <p>
 * <b>Every service below is keyed and named by its WIRE ALIAS</b> — {@code prod-qits-ci} for an
 * environment service, {@code qits-idp} for a platform one, exactly what
 * {@link PlatformModel#wireAlias} derives and exactly what the deployer will give the container
 * that replaces it. A container's own name resolves on a user-defined network the way an alias
 * does, so naming the seed after the alias is what makes the addresses in this very file right
 * from the first second rather than from the first cutover. It is
 * also how the deployer finds its predecessor: it searches the qualified alias AND the bare
 * application name, so a seed under either spelling is adopted rather than left running beside its
 * replacement.
 */
public final class ComposeTemplate {

    private ComposeTemplate() {
    }

    public static String compose(Map<String, String> values) {
        return Tokens.apply(COMPOSE.concat(COMPOSE_REST), values);
    }

    /**
     * The same file with only the named services left in it, and the reason it exists is the rule
     * every {@code depends_on} in this file was left out for: <b>a service the deployer already
     * manages must not be started beside its deployment.</b>
     * <p>
     * {@code docker stack deploy} takes a FILE and no service list — where {@code compose up} took
     * both — so the choice of what to start is made here rather than on the command line. Deployed
     * without {@code --prune}, a file naming a subset updates what it names and leaves every other
     * service of the stack alone, which is exactly what {@code compose up -d <subset>} did.
     * <p>
     * A service's own lines are everything from its key to the next one; the comment paragraph and
     * the blank line above a key belong to the service below them, which is where they are read.
     */
    public static String only(String stackFile, Collection<String> services) {
        StringBuilder kept = new StringBuilder();
        StringBuilder pending = new StringBuilder();
        boolean inServices = false;
        boolean keeping = true;
        for (String line : stackFile.split("\n", -1)) {
            if (!inServices) {
                kept.append(line).append('\n');
                inServices = "services:".equals(line);
                continue;
            }
            String key = serviceKey(line);
            if (key != null) {
                keeping = services.contains(key);
                if (keeping) {
                    kept.append(pending).append(line).append('\n');
                }
                pending.setLength(0);
            } else if (line.isBlank() || line.startsWith("  #")) {
                // Held back: it introduces whatever service comes next, and goes with it.
                pending.append(line).append('\n');
            } else if (keeping) {
                kept.append(line).append('\n');
            }
        }
        // The file ends inside a service block, so a trailing newline is all that is owed.
        return kept.toString().stripTrailing() + "\n";
    }

    /** A service key: two spaces, a name, a colon and nothing after it. Anything else is not one. */
    private static String serviceKey(String line) {
        if (!line.startsWith("  ") || line.startsWith("   ") || line.startsWith("  #")
                || !line.endsWith(":")) {
            return null;
        }
        return line.substring(2, line.length() - 1);
    }

    private static final String COMPOSE = """
            # Generated by qits-cli-bootstrap — the SEED of the local qits platform: every service phase 1
            # builds. Everything else (observability, stt, docs, orchestrator, maintenance) is
            # deployed by qits-deployments through the main pipeline and is deliberately NOT in this file —
            # look for it in `docker ps` under qits-pd-${ENV_NAME}-qits-* container names — ONE shape, since
            # the platform plane whose containers dropped the tier segment is gone — redeployed on
            # every green push.
            #
            # A STACK FILE, not a compose file: it is deployed with
            #   docker stack deploy --resolve-image never -c ${COMPOSE_FILE} qits
            # and managed with `docker stack services qits`, `docker service logs <service>` and
            # `docker stack rm qits`. (stack rm leaves deployed containers running; remove those via the
            # deployer's API or docker.)
            #
            # --resolve-image never because every image below is a LOCAL tag: qits/*:latest is built by
            # this bootstrap and no registry can resolve it to a digest.
            #
            # NO `name:` KEY. The stack name is the argument of `docker stack deploy`, and the loader
            # refuses the key outright — measured: "(root) Additional property name is not allowed".
            #
            # ONE HOST PORT IN THE WHOLE FILE: the edge's ${PORT}.
            # The byte plane — qits-artifacts, qits-mirror, qits-githost — publishes nothing
            # at all. All three are reached from the host THROUGH THE EDGE, under names of their own:
            # registry.${ENV_NAME}.localhost:${PORT}, mirror.${ENV_NAME}.localhost:${PORT} and
            # githost.${ENV_NAME}.localhost:${PORT}. systemd-resolved answers every *.localhost name
            # with the loopback address, so the host's docker daemon and a person's git both arrive
            # at the edge, which is where this platform's authentication lives: since 2026-08-14
            # EVERY method on all three names needs a bearer, reads included. On qits-net the same
            # three names are aliases of the edge — see its networks block, which says why.
            #
            # The daemon needs `insecure-registries` for the two names it dials — they are HTTP —
            # and preflight asks the DAEMON what it allows, warning when they are missing. The way in
            # when the edge itself is wedged is the break-glass script in the wrapper
            # (qits-registry-break-glass.sh), which publishes the registry's port directly for as
            # long as the repair takes. A standing publish is not that path.
            #
            # EVERY PUBLISHED PORT BINDS 0.0.0.0, and each one says so on itself: neither publish
            # mode has an ip field, so the loopback binds this file used to carry cannot be
            # expressed at all — the short form `127.0.0.1:8080:8080` is accepted and the address is
            # dropped with a warning. The exposure is written out where it can be reviewed rather
            # than discovered.

            networks:
              qits-net:
                # The one shared network: seed services, deployed applications and ci step containers all
                # join it and resolve each other by alias. It is the deployer's
                # qits.deployments.legacy-network, which every container it starts also joins while
                # the platform still holds direct cross-application URLs. External because the bootstrap (or a previous stack, or qits-ci's
                # own boot) may have created it already — a stack refuses to adopt a network it did not
                # label — and external is also what keeps the DRIVER out of the stack's hands: the
                # bootstrap creates it as an attachable overlay, because a swarm service cannot
                # attach a bridge and these plain containers still can attach an overlay.
                name: qits-net
                external: true

            volumes:
              # Every volume is keyed by the APPLICATION it belongs to, because that is the name the
              # deployer gives a repository's `private:<name>` volume: <application>-<name>.
              #
              # THERE IS NO VOLUME PER DATABASE ANY MORE. Seven services kept a file H2 under /data and
              # moved to the postgres below: the deployer, qits-ci (twice), qits-idp,
              # qits-projects, qits-workspaces, qits-events and qits-artifacts. Where /data held the H2
              # and nothing else — ci, the idp, events, the deployer — the volume is gone with it and the
              # images have no mount point left to give it. Where /data holds files as well, the volume
              # stays and only the datasource left it.
              #
              # THE BYTE PLANE HAS NO VOLUME AT ALL, and it used to have three. All three stores keep
              # their blob bytes in postgres now — qits-artifacts in qits_artifacts,
              # qits-mirror in qits_platform_mirror, qits-githost in qits_githost — so all
              # three are stateless containers with nothing to mount. What each one stores is
              # unchanged: the platform's OWN packages (npm, maven, OCI, the daemon binaries, the docs
              # bundles), what the caches pulled from upstream, and the repositories as packs and
              # reftables — a git repository on this platform was never a directory anywhere, and now
              # neither are its bytes.
              #
              # NO TWO STORES SHARE A STORE, which is why this was three volumes and never one: each
              # service's reclaim sweep counts every blob it did not put there as unreferenced and
              # deletes it. The rule survives the move — the three own a database each.
              # THE PLATFORM'S TOPOLOGY, ITS DEPLOYMENT HISTORY AND EVERY DATABASE THIS PLATFORM RUNS
              # LIVE HERE — every environment, every service, every link, every deployment row and the
              # rollback pins read off them, the credentials of every database the deployer provisions,
              # and the idp's signing key. An idp on ephemeral storage comes up healthy and mints a new
              # keypair on every recreate, invalidating every token in flight with nothing in any log to
              # say why; that is now this volume's problem to prevent rather than one of its own.
              #
              # THE MOUNT PATH IS /var/lib/postgresql AND NOT /var/lib/postgresql/data. postgres 18 puts
              # PGDATA at /var/lib/postgresql/18/docker, so a volume mounted at the old data path is
              # mounted beside the cluster rather than over it: everything works, everything is fast, and
              # every byte is written into the container's own layer and lost on the next recreate.
              qits-oci-postgresql-data:
                name: qits-oci-postgresql-data
              # Each one holds FILES that no database replaced: qits-projects' git mirrors and the
              # credentials beside them, qits-workspaces' per-repository trees, qits-stt's models.
              #
              # qits-projects' and qits-workspaces' are ALSO mounted by seed services below, and each
              # is the same volume the deployed container gets: the seed clones mirrors into it,
              # and a cutover that handed its successor an empty one would clone them all again.
              # qits-stt's is mounted by a deployed container alone.
              qits-projects-data:
                name: qits-projects-data
              qits-workspaces-data:
                name: qits-workspaces-data
              qits-stt-data:
                name: qits-stt-data
              # THE ORCHESTRATOR'S DOCKER CONFIG, and the whole volume is one file: the config.json
              # its `docker pull` authenticates with, written by the bootstrap with this service's
              # own idp client. A volume rather than env because the docker CLI reads a FILE under
              # DOCKER_CONFIG, and a mount is what a cutover carries across.
              #
              # Load-bearing since the flip, and it existed before it for that reason: a puller
              # that has to be redeployed to gain a credential is a puller that is down for the
              # length of the change.
              qits-containers-config:
                name: qits-containers-config
              # qits-system's docker config, on the orchestrator's terms: one config.json its glances
              # pull through the mirror authenticates with, written by the bootstrap with this
              # service's own idp client. The deployed successor writes its own from the client it is injected.
              qits-system-config:
                name: qits-system-config
              # The deployer's own docker config: the config.json its seed pulls authenticate with,
              # written by the bootstrap. A volume because the docker CLI reads a file. The extras
              # file that sat beside it is gone: the deployer reads its settings store (qits-765).
              qits-deployments-config:
                name: qits-deployments-config${LETSENCRYPT_VOLUME}

            # EACH KEY BELOW IS THE SERVICE'S WIRE ALIAS, AND THAT IS THE WHOLE ADDRESSING MODEL NOW.
            # There is no container_name: a stack ignores it and names the container
            # <stack>_<service>.<slot>.<taskid>. What answers the address is the SERVICE name, which
            # resolves under both `qits_<alias>` and the bare `<alias>` — measured — so the seed answers
            # to the address every peer is configured with. An
            # environment service is ${ENV_NAME}-qits-<app>; a platform service is its bare repository
            # name, which says the plane itself.
            #
            # NO update_config ANYWHERE, and that is a decision rather than an omission: swarm's default
            # update order is stop-first, which is the only order these services can take. Every one of
            # them either holds a volume no second writer may open or binds a host port a second task
            # would collide on — the deployer's config volume most of all.
            services:
              # The issuer. No published host port or public token route: in phase 1 nothing outside qits-net
              # talks to it, and /idp/token reachable from the host unauthenticated would be
              # a token vending machine. Phase 3's user flows are what put it on the route table.
              #
              # First in this file because it is first in the order that matters: every service below mints or
              # validates against it, and the git host's very first post-receive needs a token.
              ${ALIAS_IDP}:
                image: qits/idp:latest
                environment:
                  # THE STORE, and the signing key is in it: an idp that comes up on an empty database
                  # mints a new keypair and invalidates every token in flight, with nothing in any log to
                  # say why. The image ships no default for these three and refuses to boot without them.
                  #
                  # SPELLED HERE, AND ONLY HERE. This container is started by the seed stack before any deployer
                  # exists, so the bootstrap creates the role and the database over JDBC and hands the
                  # credential over itself. Every deployment after this one gets the same three variables
                  # from qits-platform-deployments, which reads `resources: postgresql:db` in this
                  # repository's deployments.yml — which is why the deployer's settings carry
                  # no datasource env at all.
                  QITS_RESOURCE_DB_URL: jdbc:postgresql://${ENV_NAME}-qits-oci-postgresql:5432/qits_platform_idp
                  QITS_RESOURCE_DB_USERNAME: qits_platform_idp
                  QITS_RESOURCE_DB_PASSWORD: "${PG_PLATFORM_IDP_PASSWORD}"
                  # Nothing is spelled for the token issuer here (qits-730). The idp derives its own `iss` —
                  # https://idp.qits.<domain> — from QITS_DOMAIN in code and reads no environment
                  # variable for it any more, so there is nothing here for this program to write
                  # or move.
                  # NO BROWSER NAMES HERE ANY MORE. The canonical origin, the return-host
                  # allow-list and the cookie domain were composed in this file and handed to the
                  # idp spelled out — three values derived from the one stated domain, each able to
                  # go stale on its own. They did: this file's list and the edge's drifted apart
                  # and sign-in broke. The domain is stated ONCE now, as QITS_DOMAIN at the foot
                  # of this block, and the idp derives its own names from it under the same
                  # right-to-left grammar everything else reads.
                  # THE ONE CLIENT THIS FILE STILL NAMES, AND IT IS THE BOOTSTRAP'S OWN. The idp
                  # seeds it into idp_service_client the first time it comes up on an empty store,
                  # and from that credential this program creates every other client against the
                  # RUNNING service — so the pair below is the whole of the platform's identity
                  # bootstrap and there is nothing else for a generated file to say.
                  #
                  # THE SEEDING IS GATED BY A MARKER ROW (idp_seed) AND NOT BY THESE VARIABLES, so
                  # they stay spelled on every boot and every rerun without seeding anything twice.
                  # Spelled they must be: `seed-idp` renders this same block to bring the idp up
                  # alone, before any client exists to create the rest with.
                  #
                  # NOTHING SAYS ROLES, CLAIMS OR AUDIENCES HERE ANY MORE, and their absence is not
                  # an omission. A database service client's role (qits:system) and its project claim
                  # (*) are fixed in qits-idp's own code — ClientRegistry.SERVICE_CLIENT_ROLES and
                  # SERVICE_CLIENT_CLAIMS — and its audience is the one platform audience every token
                  # carries, so a line here could only restate them, and a restatement is what drifts.
                  QITS_IDP_SEED_CLIENT_ID: "${BOOTSTRAP_CLIENT_ID}"
                  QITS_IDP_SEED_CLIENT_SECRET: "${BOOTSTRAP_CLIENT_SECRET}"
                  # NOR THE PASSKEY BINDING. The rp id and the ceremony's origins are the stated
                  # domain read two more ways, so they are derived from QITS_DOMAIN beside the
                  # browser names above rather than composed here. The binding itself has not
                  # moved — a credential asserts on the rp id AND its children — and the closing
                  # report is still what tells a person which host theirs is bound to.
                  # WHERE TELEMETRY GOES, and it has to be spelled in every service below. The
                  # images ship the bare qits-observability, and that name died with the
                  # 2026-08-08 rename: observability is an environment service, so its alias
                  # carries the tier. An OTLP exporter dialling a name that does not resolve drops
                  # every trace and every log AND retries, so the whole platform goes dark while
                  # each container fills its own log with the attempts — which is how it was found
                  # on the first prod bootstrap.
                  QITS_OBSERVABILITY_URL: http://${ENV_NAME}-qits-observability:8080${SEED_DOMAIN}
                # No volume: /data held the H2 and nothing else, and the image has no mount point for it
                # any more.
                #
                # The long form, because this is a platform service and the seed has to answer to
                # BOTH of its names — the bare one, which is its idp client id and this block's key,
                # and the qualified one every generated file dials. See PlatformModel.seedNetworks.
                ${SEED_NETWORKS_IDP}
                deploy:
                  replicas: 1
                  restart_policy:
                    condition: any
                    delay: 5s

              # THE HOST'S ONE HTTP PORT, and the direct deployment-route door. An unlabelled host
              # resolves to the default environment; before deployment endpoints are projected the
              # edge answers a retryable readiness response rather than proxying to a catch-all.
              #
              # In the seed because it owns public routing and catches up deployment endpoints. Seed
              # health checks use fixed service aliases because routes do not exist yet.
              ${ALIAS_EDGE}:
                image: qits/edge:latest
                ports:
                  # mode: ingress — the swarm holds this port, not the task, and that is what lets
                  # the edge redeploy ITSELF. Under `mode: host` a cutover is stop-first: the old
                  # task has to give the port up before the new one can take it, and the new one's
                  # image is pulled THROUGH THE EDGE now — a service that has to be down to come
                  # up. Ingress publishes start-first, so the predecessor keeps answering while its
                  # successor pulls, starts and passes health.
                  - target: 8080
                    published: ${PORT}
                    protocol: tcp
                    mode: ingress${EDGE_SEED_TLS_PORTS}
                environment:
                  # The whole routing surface: which environments exist, and which one an unlabelled host
                  # (localhost, an IP) resolves to. The default MUST be a member of the list — the process
                  # refuses to start otherwise, rather than letting each request find out.
                  QITS_EDGE_ENVIRONMENTS: ${ENV_NAME}
                  QITS_EDGE_DEFAULT_ENVIRONMENT: ${ENV_NAME}
                  # THE THREE APPS THAT ARE REACHED BY NAME RATHER THAN BY PATH, and this block is
                  # what closed three host ports. A request for registry.<env>.localhost goes to the
                  # first pattern, mirror.<env>.localhost to the second, githost.<env>.localhost to
                  # the third — each straight to the service,
                  # because a docker client and a git client own their own root paths (/v2, /git) and
                  # cannot be given a prefix.
                  #
                  # {env} is the EDGE's placeholder, read at runtime by the process this configures,
                  # and not a token of this generator: an app of a tier resolves to that tier's
                  # service, so one edge serves every environment on this machine.
                  #
                  # THE MIRROR CARRIES {env} NOW TOO, and it is the only one of the three whose
                  # meaning did not change when it grew one. It is still a platform service and
                  # still one cache per machine — the placeholder does not make a second one — it is
                  # that the ONE instance answers to <env>-qits-mirror as well as to its
                  # bare name, so every tier's expansion resolves to the same container. The
                  # qualifier is how the platform-service concept is retired: the address stops
                  # being a special case before the service does.
                  #
                  # EVERY METHOD ON ALL THREE NAMES STILL NEEDS A BEARER, and no name this edge
                  # serves is on an anonymous-read list — there is no such list, because
                  # QITS_EDGE_AUTH_ANONYMOUS_READ_APPS is deliberately absent. registry and mirror
                  # are gated on every method, reads included, and so is the landing page: the
                  # owner's decision on ticket qits-374 keeps it behind the login wall, so a
                  # marketing-page carve-out is not this platform's shape. Putting `registry` or
                  # `mirror` on such a list would undo the 2026-08-14 flip below — do not add the
                  # key back for any name.
                  #
                  # THE FLIP OF 2026-08-14 STANDS. Reads were anonymous on the two registry names
                  # until that day, because every puller was a machine holding no credential. Each
                  # one holds its own now — the deployer and the orchestrator from the config.json
                  # files this bootstrap writes, a ci step from the credential ci commissions for
                  # its run — so the door was closed by adding the key below, the OTHER HALF of that
                  # change, which stays exactly as it is:
                  #
                  #   QITS_PLATFORM_DEPLOYMENTS_REGISTRY_AUTH  unset (false)    ->  true
                  #
                  # ci's own half of the flip, QITS_CI_DOCKER_AUTH_HOSTS, is gone with the internal
                  # step-address plane (qits-515): a step logs in to the registries it needs from the
                  # per-run credential ci commissions and the PUBLIC names ci composes from
                  # QITS_DOMAIN, so there is no qits-net host list left to spell.
                  # NO HOST OR AUDIENCE PATTERN IS SPELLED HERE for registry, mirror or githost.
                  # The edge derives all three itself, in code, as
                  # `<env>-qits-<application>` — qits.edge.apps.<app>.host-pattern and
                  # .audience-pattern are gone from its configuration, because the pattern a platform
                  # service alias follows is a platform constant, not something a seed stack states.
                  #
                  # A PROJECT SLUG CAN NO LONGER COLLIDE WITH AN ENVIRONMENT NAME OR AN APP LABEL,
                  # because the reading is POSITIONAL: a label's meaning comes from where it sits,
                  # so an app called `prod`, a project called `registry` and an environment called
                  # `acme` are three ordinary names that are never read at the same position. The
                  # reserved slugs stay for what they still buy — a project whose slug is a
                  # published label keeps a name nobody types by mistake — and the `environment`
                  # phase keeps the mirror image of the same refusal.
                  #
                  # No port key: 8080 is the edge's default for an app, the same silence the three
                  # above keep.
                  # USER SESSIONS ARE THE DEFAULT. The environment vhost refuses an anonymous
                  # browser — a navigation is redirected to /idp/login, anything else is 401 — and
                  # turns a session cookie into X-Qits-User, X-Qits-User-Id and X-Qits-Roles.
                  # Machine credentials pass through their own validation path.
                  #
                  # The credential it introspects a session WITH is the QITS_RESOURCE_IDP_* pair
                  # below: qits-edge reads those two first and maps them onto
                  # qits.edge.sessions.client-id and .client-secret in its own application.properties,
                  # so the session gate needs no pair of its own any more. It introspects with Basic
                  # and asks for no token, so there is no oidc-client here either.
                  QITS_EDGE_SESSIONS_ENABLED: "true"
                  # AND NEITHER THE CANONICAL ORIGIN NOR THE RETURN-HOST LIST IS SPELLED HERE.
                  # Both are the stated domain read through the same right-to-left grammar the
                  # edge already applies to a request's own Host, so composing them in this file
                  # was one fact written out twice — and the second copy drifted from the idp's
                  # until a person could not sign in. The edge derives them from QITS_DOMAIN, at
                  # the foot of this block. It must be there: qits.edge.domain defaults to
                  # `localhost`, so a seed edge told nothing reads every name one tier out.
                  # THE IDP CLIENT THIS SERVICE HOLDS, AND IT IS A RESOURCE LIKE A DATABASE IS.
                  # The `idp-clients` phase creates it against the RUNNING idp — after `seed-idp`
                  # brought that service up alone — and records the secret in qits-deployments'
                  # pd_resource registry under this application and this tier. So the value below is
                  # the same row the deployer will inject as QITS_RESOURCE_IDP_* when it replaces
                  # this container, which is exactly why the seed spells the resource contract's own
                  # names rather than a service-specific pair: one identity, one registry row, two
                  # containers that never disagree about it.
                  #
                  # THE CLIENT ID IS THE WIRE ALIAS, and ${ALIAS_EDGE} is that alias — bare
                  # on the platform plane, tier-qualified otherwise, derived by the same rule the
                  # deployer's PdNetworks.alias uses. Spelling it a second way would be a copy that
                  # cannot follow a plane change.
                  QITS_RESOURCE_IDP_URL: ${IDP_DIAL}
                  QITS_RESOURCE_IDP_CLIENT_ID: ${ALIAS_EDGE}
                  QITS_RESOURCE_IDP_CLIENT_SECRET: "${IDP_CLIENT_SECRET_EDGE}"
                  QITS_RESOURCE_EDGE_URL: jdbc:postgresql://${ENV_NAME}-qits-oci-postgresql:5432/qits_platform_edge
                  QITS_RESOURCE_EDGE_USERNAME: qits_platform_edge
                  QITS_RESOURCE_EDGE_PASSWORD: "${PG_PLATFORM_EDGE_PASSWORD}"
                  QITS_RESOURCE_EVENTSTREAM_URL: jdbc:postgresql://${ENV_NAME}-qits-oci-postgresql:5432/qits_platform_edge_eventstream
                  QITS_RESOURCE_EVENTSTREAM_USERNAME: qits_platform_edge_eventstream
                  QITS_RESOURCE_EVENTSTREAM_PASSWORD: "${PG_PLATFORM_EDGE_EVENTSTREAM_PASSWORD}"
                  QITS_EVENTS_URL: http://${DIAL_EVENTS}:8080
                  QITS_OBSERVABILITY_URL: http://${ENV_NAME}-qits-observability:8080${SEED_DOMAIN}${EDGE_TLS}
                networks:
                  # THE THREE VHOSTS ARE ALIASES OF THIS SERVICE, and the long form is here for
                  # nothing else. Docker's embedded DNS answers only the names it holds and
                  # synthesizes no wildcard, so *.localhost resolves for nobody ON qits-net unless
                  # a container claims each name. An alias is how a container claims one.
                  #
                  # WHO ASKS. Everything on this network that dials a vhost rather than a wire
                  # alias, and BuildKit is the case that found it: a step container fetches its
                  # own registry token CLIENT-SIDE, so the step resolves
                  # registry.${ENV_NAME}.localhost itself instead of leaving it to the host's
                  # daemon. Without the aliases that lookup is NXDOMAIN and the push never starts.
                  #
                  # CURL IS A MISLEADING PROBE HERE. It resolves *.localhost to the loopback
                  # address ITSELF — RFC 6761 says the name is special — and asks no resolver, so
                  # a curl from inside a container answers 127.0.0.1 and proves nothing about DNS,
                  # while libc's and Go's resolvers do ask and were getting NXDOMAIN. Ask with
                  # `getent hosts` or `nslookup` instead.
                  #
                  # THESE FOUR ARE VHOSTS, not the service's own name. It carried a fifth for the
                  # platform-service retirement — its own qualified address — because the service's
                  # NAME was then the bare qits-edge while every generated file had already moved to
                  # dialling the qualified one, so the seed had to answer to both. The name IS the
                  # qualified address now, and an alias repeating it would be the same name twice.
                  qits-net:
                    aliases:
                      - registry.${ENV_NAME}.localhost
                      - mirror.${ENV_NAME}.localhost
                      - githost.${ENV_NAME}.localhost
                      - githost.${ENV_NAME}.internal
                deploy:
                  replicas: 1
                  restart_policy:
                    condition: any
                    delay: 5s

              # The platform's PostgreSQL. An ENVIRONMENT service — every tier runs its own — and the
              # deployer's own store, which is why it is in the seed at all: qits-deployments refuses to
              # boot without it, and nothing can deploy a database until the deployer answers.
              #
              # NO depends_on, here or on any consumer, and that is the resurrection rule rather than an
              # omission: on later runs this file carries only the services the deployer does not
              # already manage, and a dependency would resurrect a seed sibling beside its deployed
              # replacement. The cold path is covered by ordering instead — the seed-postgres phase has
              # this server answering before this file is even written — and the warm path by the pair
              # below it: the deployer refuses to boot without its database and the restart policy is
              # the retry loop.
              #
              # AND IT PUBLISHES NO HOST PORT. Every consumer dials this alias on 5432 over qits-net,
              # this CLI included — it runs in a container on that network. The loopback publish this
              # block used to carry had exactly one consumer, this bootstrap's cold-boot DDL, and it
              # dials the alias too. Swarm could not have kept it loopback-only in any case: a publish
              # has no ip field, so the line would have become every interface on the host. An operator
              # with a psql goes in through `docker exec`.
              #
              # No QITS_OBSERVABILITY_URL, deliberately: this is upstream postgres, not an OTLP client,
              # and the variable would be one more thing in `docker inspect` that means nothing.
              ${ENV_NAME}-qits-oci-postgresql:
                image: qits/oci-postgresql:latest
                environment:
                  # Generated by this bootstrap and recorded in .qits-bootstrap.env BEFORE the server
                  # first started. It applies at initdb only — on a volume that already holds a cluster
                  # this value is ignored, so the recorded one is the only way back in.
                  POSTGRES_PASSWORD: "${PG_SUPERUSER_PASSWORD}"
                volumes:
                  # /var/lib/postgresql, NOT /var/lib/postgresql/data — see the volume's own comment.
                  - qits-oci-postgresql-data:/var/lib/postgresql
                healthcheck:
                  # The database's own answer to "are you serving", and the same command the deployer
                  # gates its cutover with (health_cmd in this repository's deployments.yml). There is no
                  # HTTP endpoint to curl.
                  test: ["CMD-SHELL", "pg_isready -U postgres"]
                  interval: 10s
                  timeout: 5s
                  retries: 30
                networks: [qits-net]
                deploy:
                  replicas: 1
                  restart_policy:
                    condition: any
                    delay: 5s

              # The deployer, and the topology it decides from: one component, one database, one docker
              # socket. It is the merge-back of qits-cd and qits-serviceregistry, so it stands where both
              # used to. In the seed because the '${ENV_NAME}' environment is created through it minutes
              # from now and because nothing else can start a container. No published host port of its own —
              # the edge's deployment route is the public door. Ready at
              # /deployments/q/health/ready.
              #
              # A PLATFORM service since 2026-08-17: ONE deployer for every tier, so its key is the bare
              # repository name and no tier qualifies it. It was one deployer per tier until then, and the
              # move is what lets an environment gate another environment — a hierarchy cannot live inside
              # one tier's deployer. Its route segment was /platform-deployments for as long as that plane
              # existed, and the old rule for keeping it through the repository rename was right: a route
              # names the component, not the repository. The component is what moved — the platform tier is
              # retired, so the word distinguishes nothing — and the segment is /deployments now. The
              # service reroutes the old spelling internally with a WARN per hit, which is an inventory of
              # stale callers rather than a second address; for a cold boot that reroute would be the only
              # thing between a wrong segment here and a health wait that never clears.
              ${ALIAS_DEPLOYMENTS}:
                image: qits/deployments:latest
                # THE DOCKER SOCKET'S GROUP, AS THE PRIMARY ONE — and that spelling is forced.
                # `group_add` is not a stack-file key at all: the loader REFUSES the whole file
                # ("Additional property group_add is not allowed"), so it cannot even be left in to be
                # ignored. A service's supplementary groups can only be set by `docker service
                # create --group`, which a declarative seed has no place to say. `user:` is what the
                # file does have, so the socket group becomes this container's primary group.
                #
                # 1001 IS THE IMAGE'S OWN USER, restated because naming a group means naming the user
                # too. Its files are owned 1001:root, so the owner bits still apply and dropping gid 0
                # costs nothing here. THE SEED ONLY: the deployed successor is started with
                # the socket's group by the deployer itself, for the socket bind its deployments.yml
                # declares, which keeps the image's own user and adds the group beside it.
                user: "1001:${DOCKER_GID}"
                environment:
                  # ADOPTER #1 of the generic resource contract, and TWO STORES, TWO TRIPLES — the same
                  # shape ci's block below carries and for the same reason. Every application that
                  # declares `resources: postgresql:<name>` is handed
                  # QITS_RESOURCE_<NAME>_URL/_USERNAME/_PASSWORD by this very deployer; its own two
                  # arrive the same way, from the bootstrap rather than from itself. Unset, the binary
                  # refuses to boot at Flyway — which is what makes it safe to have no depends_on: a
                  # deployer that starts before its database simply restarts until the database is
                  # there.
                  #
                  # The role, the database and the username are one identity: qits_deployments.
                  #
                  # The second triple is the OUTBOX of the eventstream library the deployer joined on
                  # 2026-08-10: two Flyway lineages cannot share one database. The library reads the
                  # `eventstream` name in its own shipped defaults, so that spelling is not a choice
                  # made here.
                  #
                  # SPELLED HERE, AND ONLY HERE. Compose starts this container before any deployer
                  # exists, so the bootstrap created both roles and databases over JDBC. Every
                  # deployment after this one is handed the same six variables by a RUNNING deployer,
                  # from `resources: postgresql:db, postgresql:eventstream:qits_deployments_eventstream`
                  # in this repository's deployments.yml — which is why the deployer's settings carry
                  # neither triple.
                  QITS_RESOURCE_DB_URL: jdbc:postgresql://${ENV_NAME}-qits-oci-postgresql:5432/qits_deployments
                  QITS_RESOURCE_DB_USERNAME: qits_deployments
                  QITS_RESOURCE_DB_PASSWORD: "${PG_DEPLOYMENTS_PASSWORD}"
                  QITS_RESOURCE_EVENTSTREAM_URL: jdbc:postgresql://${ENV_NAME}-qits-oci-postgresql:5432/qits_deployments_eventstream
                  QITS_RESOURCE_EVENTSTREAM_USERNAME: qits_deployments_eventstream
                  QITS_RESOURCE_EVENTSTREAM_PASSWORD: "${PG_DEPLOYMENTS_EVENTSTREAM_PASSWORD}"
                  # The event bus, and the same override the seed ci carries one block down. Spelled
                  # although the bus is a platform service now and the eventstream jar's shipped
                  # `qits-events:8080` therefore resolves: an address a deployment inherits silently is
                  # one nobody knows to change, and this value follows the wire alias so a later rename
                  # moves both sides at once. The deployer SUBSCRIBES durably here — a BuildSuccessful it
                  # never receives is a deployment that never happens — so a wrong value costs more than
                  # a lost publish.
                  QITS_EVENTS_URL: http://${DIAL_EVENTS}:8080${TIER_ENV_DEPLOYMENTS}
                  # WHERE IT READS A DEPLOYMENT SPEC. It was a plain property in the extras file this
                  # service read at boot from its config volume; what the deployer configures ITSELF
                  # with is env. The spec read is how a green build becomes a deployment, so a
                  # deployer without this deploys nothing and says only "timeout". The address is the
                  # git host's own alias, never the edge: this is a trusted service-to-service read and
                  # the edge strips forwarded identity headers by design.
                  QITS_PLATFORM_DEPLOYMENTS_GIT_HOST_URL: http://${ENV_NAME}-qits-githost:8080
                  # THE ADMIN CREDENTIAL, and what makes this component a provisioner rather than only a
                  # consumer: it is what lets it create the role and the database of every application
                  # that declares one. It lives in the same trust domain as the docker socket beside it.
                  QITS_PLATFORM_DEPLOYMENTS_POSTGRES_ADMIN_PASSWORD: "${PG_SUPERUSER_PASSWORD}"
                  # It pulls through the HOST DAEMON, which resolves the reference this deployer now
                  # DERIVES itself — registry.qits.<domain>, from the QITS_DOMAIN line below — rather
                  # than a value stated here. There is no registry-host key left to spell: every pull
                  # still carries a bearer, which is what the two variables below are for.
                  # WHERE THE DOCKER CLI LOOKS FOR A CREDENTIAL. This container runs as uid 1001
                  # with no home, so without this variable docker finds no ~/.docker/config.json
                  # and pulls anonymously, which the edge now refuses. The bootstrap writes
                  # config.json onto the config volume below, and this variable is what makes the CLI
                  # read it. The identity in it is this service's own idp client,
                  # ${ALIAS_DEPLOYMENTS}.
                  DOCKER_CONFIG: /work/config
                  # AND THE SWITCH THAT MAKES IT LOAD-BEARING — one of the flip's three values,
                  # spelled here as well as in the deployer's settings, because this seed deployer
                  # pulls before its settings store holds a row. It does two things: this deployer's
                  # own `docker pull`
                  # authenticates, and the credential is serialised into each service spec it
                  # creates, so the swarm agent's own pull on every node carries it too. False —
                  # its shipped default, and the rollback — is a deployer that can pull nothing.
                  QITS_PLATFORM_DEPLOYMENTS_REGISTRY_AUTH: "true"
                  # WHAT EVERY OTHER APPLICATION IS DEPLOYED WITH IS NOT HERE. The deployer takes each
                  # deployment's environment from its settings store, which the deployment-settings
                  # phase fills once this service answers; what IS env here is what this deployer
                  # configures itself with until its own self-update reads its own rows.
                  # Machine auth, INBOUND ONLY. The build-succeeded intake and the topology writes demand a
                  # bearer addressed to this service; every read stays open.
                  #
                  # NO AUDIENCE LINE, and the absence is the platform's rule rather than this
                  # service's exception: every image ships
                  # quarkus.oidc.token.audience=qits-platform, one literal name for the whole
                  # platform, and the idp puts that name on every token it mints whatever the
                  # caller asked for. So a bearer is accepted without anybody stating an audience,
                  # and there is no per-service name for a line here to say.
                  QITS_AUTH_MACHINE_REQUIRED: "${MACHINE_REQUIRED}"
                  # ITS OWN IDP CLIENT, as the resource triple — see the edge's block for why a
                  # credential this program creates is spelled the way the deployer will inject it.
                  # This one is the seam's own: the deployer both HOLDS this row and is the service
                  # that hands every other application its own.
                  QITS_RESOURCE_IDP_URL: ${IDP_DIAL}
                  QITS_RESOURCE_IDP_CLIENT_ID: ${ALIAS_DEPLOYMENTS}
                  QITS_RESOURCE_IDP_CLIENT_SECRET: "${IDP_CLIENT_SECRET_DEPLOYMENTS}"
                  QUARKUS_OIDC_AUTH_SERVER_URL: ${IDP_DIAL}
                  QITS_OBSERVABILITY_URL: http://${ENV_NAME}-qits-observability:8080${SEED_DOMAIN}
                volumes:
                  # No data volume any more: the store is the postgres above, and /data held the H2 files
                  # and nothing else. The config volume stays for the docker credential above.
                  - qits-deployments-config:/work/config
                  - /var/run/docker.sock:/var/run/docker.sock
                # Both names, for the reason spelled on qits-idp's block above.
                ${SEED_NETWORKS_DEPLOYMENTS}
                deploy:
                  replicas: 1
                  restart_policy:
                    condition: any
                    delay: 5s
            """;

    /**
     * The same file, continued. <b>The split is the class-file limit and nothing else</b>: a string
     * constant cannot exceed 65535 UTF-8 bytes, and this template passed it on 2026-08-14 —
     * "constant string too long", at the declaration rather than at the line that grew. The two
     * halves are joined with {@code concat} rather than {@code +} because the compiler folds a
     * concatenation of two constants back into one constant and refuses it again. Split at a
     * service boundary so no block is cut in half.
     */
    private static final String COMPOSE_REST = """

              # THE PLATFORM'S OWN PACKAGES, and nothing third-party: the hosted npm registry, the hosted
              # maven repository, the hosted OCI registry, the daemon binaries and the docs bundles. An
              # ENVIRONMENT service again since the byte-plane split — the pull-through caches below are
              # what made it platform-scoped, and they left.
              #
              # NO PUBLISHED PORT, and the host still pulls and pushes here. The door is the edge:
              # registry.${ENV_NAME}.localhost:${PORT} is what the host's docker daemon dials for
              # this bootstrap's own seed pulls. It resolves to the loopback address like every
              # *.localhost name, arrives at the edge, and the edge hands it to this service by that
              # name — reads anonymous, writes with a bearer. The port this block used to publish
              # was open to anything that could reach the host. A deployment reaches this same
              # service through a different, public name once it is live — registry.qits.<domain> —
              # which qits-deployments now derives rather than a deployment stating it.
              #
              # The daemon needs the name in `insecure-registries` (plain HTTP), which preflight
              # warns about and the closing report spells. When the edge itself is wedged, the way
              # back in is the wrapper's qits-registry-break-glass.sh, which opens a direct port for
              # as long as the repair takes and closes it again.
              ${ENV_NAME}-qits-artifacts:
                image: qits/artifacts:latest
                environment:
                  # THE WHOLE STORE, and there is nothing beside it to mount. Metadata and blob bytes are
                  # both rows in qits_artifacts, so this container is stateless: a restart loses in-flight
                  # upload sessions and nothing else.
                  #
                  # SPELLED HERE, AND ONLY HERE, exactly as the mirror's and the git host's are: the seed
                  # stack starts this container before any deployer exists, so the bootstrap created the
                  # role and the database over JDBC and hands the credential over itself. Every
                  # deployment after this one is handed the same three by qits-platform-deployments, from
                  # `resources: postgresql:db` in this repository's deployments.yml — which is why the
                  # deployer's settings carry no datasource env either.
                  QITS_RESOURCE_DB_URL: jdbc:postgresql://${ENV_NAME}-qits-oci-postgresql:5432/qits_artifacts
                  QITS_RESOURCE_DB_USERNAME: qits_artifacts
                  QITS_RESOURCE_DB_PASSWORD: "${PG_ARTIFACTS_PASSWORD}"
                  # Machine auth, INBOUND ONLY. The admin writes under /artifacts/api demand a bearer
                  # addressed to this service; every read stays open. There is no oidc-client and no
                  # secret any more: the one thing this service ever minted a token for was the git
                  # host's post-receive announcement, and the git host is qits-githost now — which
                  # publishes on the bus and mints nothing.
                  #
                  # NO AUDIENCE LINE EITHER: the image validates qits-platform out of its shipped
                  # quarkus.oidc.token.audience, which is the one name every minted token carries,
                  # so nothing here has to say which name a caller may address. See the deployer's
                  # block.
                  QITS_AUTH_MACHINE_REQUIRED: "${MACHINE_REQUIRED}"
                  QUARKUS_OIDC_AUTH_SERVER_URL: ${IDP_DIAL}
                  QITS_OBSERVABILITY_URL: http://${ENV_NAME}-qits-observability:8080${SEED_DOMAIN}
                networks: [qits-net]
                deploy:
                  replicas: 1
                  restart_policy:
                    condition: any
                    delay: 5s

              # EVERYTHING THIRD-PARTY A BUILD RESOLVES, cached: npmjs, Maven Central, Docker Hub, quay.io
              # and the Red Hat registry, each behind a pull-through cache with its own eviction window.
              #
              # A PLATFORM service, and the only byte service that is: a cache of Maven Central is one
              # cache for a machine however many tiers run on it. That was qits-platform-artifacts' only
              # reason to be platform-scoped, and this is what is left of it.
              #
              # In the seed because everything else is downstream of it. Every seed publish resolves its
              # third-party dependencies here, every image build pulls its base layers here, and a cache
              # that is not up yet is not a slow build but a failed one. It starts COLD and warms up: the
              # first of each fetch pays the upstream, and nothing has to be pre-loaded.
              #
              # NO PUBLISHED PORT EITHER, and the third-party door is a NAME now:
              # mirror.${ENV_NAME}.localhost:${PORT}, through the edge. It used to be a second host
              # port rather than a path for a reason that has not changed — this service and the
              # store both answer the literal prefixes /artifacts/npm, /artifacts/maven and /v2, so
              # the client's configuration is what picks between them. What picks now is the NAME:
              # every committed Dockerfile spells mirror.<env>.localhost in its FROM lines, and
              # dockerd's registry-mirrors names the same host. The name needs an
              # `insecure-registries` entry of its own; the registry's is not enough.
              ${ALIAS_MIRROR}:
                image: qits/mirror:latest
                environment:
                  # SPELLED HERE, AND ONLY HERE, exactly as the idp's and the bus's are: the seed stack starts
                  # this container before any deployer exists, so the bootstrap created the role and the
                  # database over JDBC and hands the credential over itself. Every deployment after this
                  # one is handed the same three by qits-platform-deployments, from `resources:
                  # postgresql:db` in this repository's deployments.yml — which is why the deployer's
                  # settings carry no datasource env either.
                  QITS_RESOURCE_DB_URL: jdbc:postgresql://${ENV_NAME}-qits-oci-postgresql:5432/qits_platform_mirror
                  QITS_RESOURCE_DB_USERNAME: qits_platform_mirror
                  QITS_RESOURCE_DB_PASSWORD: "${PG_PLATFORM_MIRROR_PASSWORD}"
                  # AND THE CACHED BYTES ARE IN THERE TOO. There is no blobs directory and no volume:
                  # what this service pulled from upstream is rows in the same database, so the
                  # container is stateless and a cold start is the ordinary one anyway.
                  QITS_OBSERVABILITY_URL: http://${ENV_NAME}-qits-observability:8080${SEED_DOMAIN}
                # Both names, for the reason spelled on qits-idp's block above.
                ${SEED_NETWORKS_MIRROR}
                deploy:
                  replicas: 1
                  restart_policy:
                    condition: any
                    delay: 5s

              # THE GIT HOST. A service of its own since the byte-plane split: a repository was never an
              # artifact, it only shared the storage — packs, pack indexes and reftables are ordinary
              # content-addressed blobs, which is why this service needs a store and not a directory.
              #
              # An ENVIRONMENT service, because every one of its consumers already was one: qits-ci,
              # qits-projects, qits-workspaces, the daemons and the workspace containers.
              #
              # In the seed because the first push of this boot goes to it. Nothing can be built out of a
              # repository nothing hosts, and every repository this platform has is created here minutes
              # from now.
              #
              # NO PUBLISHED PORT, and the host-side git door stayed open: it is
              # http://githost.${ENV_NAME}.localhost:${PORT}/git/<projectId>/<repo>.git through the
              # edge. A person clones and pushes from the workstation, which is not on qits-net, and
              # the url has moved three times — localhost:8081/artifacts/git/<repo> while
              # the routes lived in the store, then a port of its own after the split, then a name,
              # and now the project-scoped pair. /git/<repoId> is the STORAGE scheme underneath it,
              # qits-projects' internal address for the same bare, and no person ever holds one.
              #
              # EVERY METHOD NEEDS A BEARER HERE, reads included: this is not a registry and there is
              # no anonymous half. `curl -u <client>:<secret> .../token`, then git with the header —
              # the closing report prints the pair.
              #
              # This bootstrap does not use any of it: every phase that pushes runs inside a container
              # that joined qits-net, so it dials the alias like every other member.
              ${ENV_NAME}-qits-githost:
                image: qits/githost:latest
                environment:
                  # TWO STORES, TWO TRIPLES, the same shape ci's block carries and for the same reason:
                  # this service's own pack catalog and the outbox of the eventstream library are two
                  # Flyway lineages and cannot share one database. The library reads the `eventstream`
                  # name in its own shipped defaults, so that spelling is not a choice made here.
                  #
                  # SPELLED HERE, AND ONLY HERE: the seed stack starts this container before any deployer
                  # exists. Later deployments are handed the same six by qits-platform-deployments from
                  # `resources: postgresql:db, postgresql:eventstream:qits_githost_eventstream`.
                  QITS_RESOURCE_DB_URL: jdbc:postgresql://${ENV_NAME}-qits-oci-postgresql:5432/qits_githost
                  QITS_RESOURCE_DB_USERNAME: qits_githost
                  QITS_RESOURCE_DB_PASSWORD: "${PG_GITHOST_PASSWORD}"
                  QITS_RESOURCE_EVENTSTREAM_URL: jdbc:postgresql://${ENV_NAME}-qits-oci-postgresql:5432/qits_githost_eventstream
                  QITS_RESOURCE_EVENTSTREAM_USERNAME: qits_githost_eventstream
                  QITS_RESOURCE_EVENTSTREAM_PASSWORD: "${PG_GITHOST_EVENTSTREAM_PASSWORD}"
                  # WHERE THE REPOSITORIES LIVE: the first of those two databases, and nowhere else.
                  # Packs, pack indexes and reftables are rows in qits_githost, so there is no blobs
                  # directory to spell and no volume to mount — this container is stateless like the
                  # other two byte services.
                  # WHAT A PUSH BECOMES. SCMPublishCommit, SCMPublishTag and the two deletes go through
                  # the eventstream outbox to the bus, where qits-ci's durable listener turns a commit
                  # into a run and qits-projects' turns it into a backup. It REPLACES the post-receive
                  # HTTP fan-out, which retried in memory for three minutes and then lost the event —
                  # twice on this platform, both times during a consumer's redeploy. Stated rather than
                  # left to the jar's shipped qits-events:8080, which the bus's move to the platform
                  # plane finally made a resolvable name: the value follows the wire alias, so the
                  # repository rename ahead of us moves this line with it.
                  QITS_EVENTS_URL: http://${DIAL_EVENTS}:8080
                  # WHAT TURNS /git/:projectId/:repoName INTO A REPOSITORY, AND NO VARIABLE SPELLS IT.
                  # The git host keeps (projectId, repoName) -> repository in its own database now;
                  # qits-projects states it there with PUT /git/{repoId}/names after every name
                  # change (create, adopt, rename, alias) and reconciles the whole table every five
                  # minutes, so there is nothing to configure on this side. The public url serves as
                  # soon as qits-projects has registered (adopted) the repository — normally within
                  # that same call — and qits-projects is a seed service since 2026-08-21, which is
                  # what lets every push of this boot be name-addressed.
                  # NO qits.githost.storage-client HERE, AND THE ABSENCE IS THE STAGING.
                  # Set, that key closes /git/<repoId> to qits-projects' client and to nothing else —
                  # which is right for the platform this run leaves behind and impossible for the run
                  # itself. The bootstrap CREATES every repository on this seed service, over that
                  # exact scheme, with its own credential, and that credential is the BOOTSTRAP's —
                  # never qits-projects'. Seeding qits-projects did not change it: what the guard
                  # demands is one client's self-role, and the party creating the bares holds a
                  # different one. So the seed serves the compat arm and the guard arrives with the
                  # git host's OWN deployment, which leaves the guard at the image's default, by which
                  # time `git-repos` has given every repository a name and this run addresses nothing
                  # else.
                  # NO QITS_BOOTSTRAP_INGRESS_GIT_*: the bootstrap ingress serves the progress page
                  # alone, so the git host's /bootstrap-git route keeps its shipped default — off.
                  # The default branch's escape hatch: a push carrying -o qits.token=<this> is let through
                  # even when protection is on. Unset would mean no value matches and nothing overrides —
                  # which is the shipped default, and which this bootstrap cannot live with (it pushes
                  # main many times before a release endpoint exists to go through).
                  QITS_REPOSITORIES_GIT_PUSH_TOKEN: "${PUSH_TOKEN}"
                  # Protection stays ON: the bootstrap's own pushes carry the token above, and a rerun
                  # that silently disarmed the seatbelt would be the quiet failure. The service ships it
                  # FALSE, because it is the git host that serves its own redeploy.
                  QITS_REPOSITORIES_GIT_PROTECT_DEFAULT_BRANCH: "true"
                  QITS_OBSERVABILITY_URL: http://${ENV_NAME}-qits-observability:8080${SEED_DOMAIN}
                networks: [qits-net]
                deploy:
                  replicas: 1
                  restart_policy:
                    condition: any
                    delay: 5s

              # THE ALIAS TABLE'S OWNER, and the reason a repository on this platform has a name at
              # all. /git/<projectId>/<repoName> is the one clone url there is, and qits-githost keeps
              # that table in its own database now; this service is what STATES it there, with PUT
              # /git/{repoId}/names after every name change and a five-minute reconcile behind it, so
              # the public url serves once this service has registered (adopted) the repository.
              #
              # In the seed since 2026-08-21, and the ruling of that day is why. A storage id is an
              # opaque UUID now, so a name resolves through this service or nowhere: seeded, every
              # repository this run creates is registered before it is pushed to, and every push of
              # the boot carries the two name fields onto its event. Deployed sixth of seventeen
              # instead, it answered nothing for the first half of the boot — which is why the ids
              # used to be spelled like the names.
              #
              # WHAT IT NEEDS AT SEED TIME, and each one is a boot that fails without it:
              # three databases (below), a git host to create bares on, an idp to cut the bearer
              # that git host demands, and somewhere to keep its mirrors. What it does NOT need is
              # the container orchestrator: nothing on the seeding path starts a workload, and an
              # unreachable one is a warning on a five-minute sweep.
              ${ENV_NAME}-qits-projects:
                image: qits/projects:latest
                environment:
                  # THREE STORES, THREE TRIPLES — the only service here with three, and its own
                  # deployments.yml is where the count comes from: `resources: postgresql:db,
                  # postgresql:epics:qits_epics, postgresql:eventstream:qits_projects_eventstream`.
                  # Its domain rows, the epics beside them and the eventstream outbox are three
                  # Flyway lineages and no two of them may share a database.
                  #
                  # SPELLED HERE, AND ONLY HERE, like the git host's six above: the seed stack starts
                  # this container before any deployer exists. The urls are expressions with no
                  # fallback behind them, so one missing variable is not a misconfiguration anybody
                  # sees — it is a process that dies at Flyway naming it.
                  QITS_RESOURCE_DB_URL: jdbc:postgresql://${ENV_NAME}-qits-oci-postgresql:5432/qits_projects
                  QITS_RESOURCE_DB_USERNAME: qits_projects
                  QITS_RESOURCE_DB_PASSWORD: "${PG_PROJECTS_PASSWORD}"
                  QITS_RESOURCE_EPICS_URL: jdbc:postgresql://${ENV_NAME}-qits-oci-postgresql:5432/qits_epics
                  QITS_RESOURCE_EPICS_USERNAME: qits_epics
                  QITS_RESOURCE_EPICS_PASSWORD: "${PG_EPICS_PASSWORD}"
                  QITS_RESOURCE_EVENTSTREAM_URL: jdbc:postgresql://${ENV_NAME}-qits-oci-postgresql:5432/qits_projects_eventstream
                  QITS_RESOURCE_EVENTSTREAM_USERNAME: qits_projects_eventstream
                  QITS_RESOURCE_EVENTSTREAM_PASSWORD: "${PG_PROJECTS_EVENTSTREAM_PASSWORD}"
                  # THE SELF-SEED IS HELD, AND THE BOOTSTRAP RELEASES IT. This service creates the
                  # `qits` project itself on a first boot — nothing else may, or one platform ends
                  # up with two projects of one name — and that act clones the wrapper from the org
                  # and creates its bare on the git host, which needs a bearer the idp mints. The
                  # seed stack starts every service at once, so a self-seed that fired while the idp
                  # was still coming up would fail, roll its own transaction back and NOT try again
                  # until the container restarts. The `qits-project` phase turns this on once the
                  # idp has answered, and then waits for the project.
                  QITS_STARTUP_SEED_ENABLED: "false"
                  # AND ITS SECOND HALF STAYS OFF FOR THE WHOLE SEED. The self-seed creates the
                  # project and then RECONCILES the wrapper's .gitmodules: an entry it holds no row
                  # for is looked up on the git host by NAME, and under the ruling of 2026-08-21 no
                  # storage id is a name — so on a fresh platform every entry misses and the
                  # reconcile takes its remaining arm, which is to mirror all 43 repositories in
                  # from the org. That would run minutes before this bootstrap has created a single
                  # bare, and the platform's history would come from the forge rather than from the
                  # checkouts this boot was told to build. So the seed creates the project only, the
                  # bootstrap registers every (uuid, name) pair itself, and the reconcile runs for
                  # the first time on the DEPLOYED container — where every entry now matches a row
                  # by alias and nothing is cloned.
                  QITS_STARTUP_SEED_RECONCILE_REPOSITORIES: "false"
                  # THE SLUGS NO PROJECT MAY TAKE, AND THERE ARE TWO KINDS OF THEM: this platform's
                  # environment name, and every LABEL this platform already publishes.
                  #
                  # NEITHER KIND IS A MISROUTE ANY MORE, and the list is kept for what it still
                  # buys. The edge reads <app>[.<env>].<project>.<domain> POSITIONALLY — a label's
                  # meaning comes from where it sits — so a project called `prod` and a project
                  # called `registry` both route correctly: the project label is read at the
                  # project position and nowhere else. What a slug that spells a published label
                  # still costs is a name people mistype and a door that reads like an app's, so
                  # the refusal stands; it is the only moment the name can still be changed. The
                  # `environment` phase refuses the mirror image, an environment named after a
                  # project that already exists.
                  #
                  # DERIVED, NOT WRITTEN — PlatformModel.reservedSlugs builds it from the
                  # deployables' own browser labels plus the edge's four app entries, so an
                  # application this bootstrap gains reserves its label without anybody editing a
                  # list. Environment first, then the labels sorted, so a rerun writes what the
                  # last run wrote.
                  QITS_PROJECTS_RESERVED_SLUGS: ${RESERVED_SLUGS}
                  # Where its own git mirrors go. The image defaults it under ${user.home}, which is
                  # the literal "?" for this passwd-less uid — the same trap the image's own default
                  # avoids for a deployed container.
                  QITS_PROJECTS_DATA_DIR: /data/mirrors
                  # The git host, scheme host and port with no path: this service appends
                  # /git/<repoId> itself, and it is the ONE caller allowed to speak that scheme.
                  QITS_GITHOST_URL: http://${ENV_NAME}-qits-githost:8080
                  # The same token the git host's hook checks: this service advances refs by
                  # pushing, and the default branch is protected here.
                  QITS_REPOSITORIES_GIT_PUSH_TOKEN: "${PUSH_TOKEN}"
                  QITS_PROJECTS_OWN_HOST: ${ENV_NAME}-qits-projects
                  QITS_PROJECTS_CONTAINER_GIT_URL: http://githost.${ENV_NAME}.internal:8080
                  QITS_CONTAINERS_URL: http://${ENV_NAME}-qits-containers:8080
                  QITS_EVENTS_URL: http://${DIAL_EVENTS}:8080
                  # Inbound: the bootstrap's own calls carry a bearer addressed to this service.
                  # Outbound: ONE CREDENTIAL AND NO NAMED CLIENTS. Every git-host call this service
                  # makes refuses to open a socket without a bearer, and what it mints them from is
                  # the resource triple below — the image builds its oidc clients over
                  # qits.resource.idp.*, so a named client per peer, spelled here in five env lines
                  # each, would be a second copy of one identity with its own spelling of the
                  # secret.
                  QITS_AUTH_MACHINE_REQUIRED: "${MACHINE_REQUIRED}"
                  QUARKUS_OIDC_AUTH_SERVER_URL: ${IDP_DIAL}
                  # ITS OWN IDP CLIENT, as the resource triple — see the edge's block for why a
                  # credential this program creates is spelled the way the deployer will inject it.
                  QITS_RESOURCE_IDP_URL: ${IDP_DIAL}
                  QITS_RESOURCE_IDP_CLIENT_ID: ${ALIAS_PROJECTS}
                  QITS_RESOURCE_IDP_CLIENT_SECRET: "${IDP_CLIENT_SECRET_PROJECTS}"
                  QITS_OBSERVABILITY_URL: http://${ENV_NAME}-qits-observability:8080${SEED_DOMAIN}
                # THE SAME VOLUME THE DEPLOYED CONTAINER GETS, and it is the only seed service that
                # mounts one it shares with its successor. /data is not a database — it is the git
                # mirrors this service clones and the credential file beside them — so a cutover
                # onto an empty volume would re-clone the wrapper it already has.
                volumes:
                  - qits-projects-data:/data
                networks: [qits-net]
                deploy:
                  replicas: 1
                  restart_policy:
                    condition: any
                    delay: 5s

              ${ENV_NAME}-qits-ci:
                image: qits/ci:latest
                # NO SOCKET AND NO SOCKET GROUP, and that is the attack surface this cutover buys.
                # ci held the host's docker socket to run every pipeline step, which is root on the
                # host — and every step's script is repo-controlled code, so the one service most
                # exposed to untrusted input was also the one holding the daemon. Since qits-443
                # retired ci's in-process executor it starts no step itself at all — every run is
                # a CI lease on a qits-system target since qits-1547 — and it calls qits-containers
                # for nothing. Do
                # not mount the socket back: nothing in the image reads it, and `docker` is not on
                # this image's PATH.
                environment:
                  # TWO STORES, TWO TRIPLES. ci's own database and the outbox of the eventstream library
                  # it joins are two Flyway lineages and cannot share one. The library reads the
                  # `eventstream` name in its own shipped defaults, so the second triple's spelling is
                  # not a choice made here. Its file-H2 predecessor sat under ${user.home}, which a
                  # container has not got — that is gone with the H2.
                  #
                  # SPELLED HERE, AND ONLY HERE, for the same reason as the idp's above: the seed stack starts
                  # this container before any deployer exists. Later deployments are handed the same six
                  # variables by qits-platform-deployments, from
                  # `resources: postgresql:db, postgresql:eventstream:qits_ci_eventstream` in this
                  # repository's deployments.yml.
                  QITS_RESOURCE_DB_URL: jdbc:postgresql://${ENV_NAME}-qits-oci-postgresql:5432/qits_ci
                  QITS_RESOURCE_DB_USERNAME: qits_ci
                  QITS_RESOURCE_DB_PASSWORD: "${PG_CI_PASSWORD}"
                  QITS_RESOURCE_EVENTSTREAM_URL: jdbc:postgresql://${ENV_NAME}-qits-oci-postgresql:5432/qits_ci_eventstream
                  QITS_RESOURCE_EVENTSTREAM_USERNAME: qits_ci_eventstream
                  QITS_RESOURCE_EVENTSTREAM_PASSWORD: "${PG_CI_EVENTSTREAM_PASSWORD}"
                  # ci's own fetch of the pushed ref.
                  #
                  # THE GIT HOST'S ROOT, WITH NO PATH: ci appends the repository's own address
                  # itself — /git/<projectId>/<repoName> for a run that carries names, and the
                  # storage scheme for one whose announcing push was id-addressed. It used to be
                  # /artifacts, because the routes lived inside the artifacts store; qits-githost
                  # serves /git at its own root and there is nothing in front of it.
                  QITS_CI_GIT_HOST_URL: http://${ENV_NAME}-qits-githost:8080
                  # THE SAME CATALOGUE THE DEPLOYED ci READS, on the seed too — since 2026-09-05.
                  # The seed used to withhold this key, on the argument that qits-projects was
                  # deployed fourteen phases after this container and a configured catalogue REPLACES
                  # the git host's listing, so the seed would have met every early event with an empty
                  # candidate list. Both halves of that argument are stale: qits-projects is a SEED
                  # service in this same stack, its catalogue is filled by the qits-project and
                  # git-repos phases, and the first event ci ever sees is the release-train push that
                  # follows them. What the id-only listing cost is measured, not argued: a run built
                  # from it carries no project, so QITS_CI_REPOSITORY_URL is /git/<storage uuid> and
                  # every recipe that derives a sibling from it — the frontend-submodule clones of
                  # observability and platform-idp — asks for /git/<name> and gets a
                  # 404 (2026-09-05 trial boot, deploy phases 60–62). The deployed ci never had that
                  # problem; the seed now says the same thing.
                  QITS_CI_PROJECTS_URL: http://${ENV_NAME}-qits-projects:8080
                  # NOT the bound on a build. It is the step CONTAINER's limit; a `docker build` a
                  # step runs is served by the HOST daemon and is outside this cgroup entirely.
                  QITS_CI_MEMORY_LIMIT: 4g
                  QITS_CI_CPUS: "4"
                  # THE SEED qits-ci HAS NO EXECUTOR OF ITS OWN since qits-443 retired the in-process
                  # one: QITS_CONTAINERS_URL, QITS_CI_CONCURRENT_BUILDS and
                  # QITS_CI_IN_PROCESS_EXECUTOR_ENABLED are gone with it, and this seed container
                  # never calls qits-containers. Every run of this boot is executed by the
                  # `localhost` runner the bootstrap starts as a plain container on the default
                  # bridge, no platform network (qits-588), over the public edge — see the
                  # QITS_DOMAIN note below.
                  # NO QITS_PLATFORM_DEPLOYMENTS_INTAKE_URL. ci's direct POST to the deployer was retired
                  # on 2026-08-10: a green build is announced on the BUS now, ci -> outbox ->
                  # ${ALIAS_EVENTS} -> the deployer's durable subscriber. qits-ci reads no such key
                  # any more, and a value nothing reads is a lie waiting to age. The deployer's HTTP intake
                  # stays as the manual door — this bootstrap's own build-event replay uses it.
                  # NO registry-host key any more: a publish step's registry is the PUBLIC name
                  # qits-ci composes itself from QITS_DOMAIN below (registry.qits.<domain>), the
                  # same derivation qits-deployments now uses for a pull — never a value stated
                  # here.
                  # NO QITS_CI_REGISTRY_AUTH_*, and its retirement is the commission API's dividend.
                  # A publish step still needs a credential — the edge answers a registry WRITE with
                  # a 401 Bearer challenge — but ci no longer holds a static one to lend out: it
                  # commissions a credential from qits-idp for the RUN, with its own client
                  # id and secret, and decommissions it when the run ends. It borrowed the store's
                  # own client for half a day, which made one leaked step secret the identity that
                  # may write to every registry on the platform. Nothing goes here in its place.
                  # qits-ci REACHES its own artifact store at this alias, on qits-net — HttpImagePins'
                  # own use of the hosted Maven repository, not a step's. A step is told the PUBLIC
                  # name of every store it needs, composed by qits-ci itself from QITS_DOMAIN; the
                  # internal step-address plane that used to spell npm/docs/workspaces roots and a
                  # step daemon callback here is retired (qits-515).
                  QITS_ARTIFACTS_MAVEN_REGISTRY_URL: http://${ENV_NAME}-qits-artifacts:8080/artifacts/maven/maven
                  # The event bus. Its shipped `qits-events:8080` resolved to nothing while the bus
                  # was per-tier — measured: every outbox delivery of the seed ci dialled it, got
                  # ConnectException, and gave up after its five attempts. The bus is a platform
                  # service since 2026-08-17 and the name resolves; the line stays, valued from the
                  # wire alias, like every other address in this block.
                  QITS_EVENTS_URL: http://${DIAL_EVENTS}:8080
                  # The binary every step container downloads and execs — uploaded by this bootstrap, digest
                  # pinned. Blank would mean every run fails as never-registered.
                  #
                  # SPELLED AS THE OVERRIDE, deliberately: qits-ci's ordinary answer is the version of
                  # the eu.wohlben.qits:qits-ci-daemon-protocol jar it pins, which is the version of the
                  # binary released beside it, and a freshly bootstrapped platform has released nothing —
                  # its only daemon binary is this digest, uploaded by this bootstrap and named by
                  # nothing else. The override is exactly the hatch a digest belongs in. Once this
                  # platform has released a daemon and qits-ci's pin has moved to that version, clearing
                  # this entry is what hands the decision back to the pin. The retired name
                  # QITS_CI_DAEMON_VERSION is read by nobody; qits-ci WARNs at boot if it finds it set.
                  QITS_CI_DAEMON_VERSION_OVERRIDE: "${DAEMON_SHA}"
                  # Machine auth. Inbound: /ci/api/events/* demands a bearer addressed to this service whose
                  # project claim covers the event's repo. Outbound: every request that starts, reads
                  # or removes a step container carries one.
                  QITS_AUTH_MACHINE_REQUIRED: "${MACHINE_REQUIRED}"
                  QUARKUS_OIDC_AUTH_SERVER_URL: ${IDP_DIAL}
                  # ITS OWN IDP CLIENT, as the resource triple — see the edge's block for why a
                  # credential this program creates is spelled the way the deployer will inject it.
                  QITS_RESOURCE_IDP_URL: ${IDP_DIAL}
                  QITS_RESOURCE_IDP_CLIENT_ID: ${ALIAS_CI}
                  QITS_RESOURCE_IDP_CLIENT_SECRET: "${IDP_CLIENT_SECRET_CI}"
                  # NO SWITCH BESIDE THE TRIPLE ANY MORE. qits-ci's one oidc client used to ship off
                  # and read an env override of its own alone to turn it on; qits-711 made the
                  # client resource-only and enabled by default (client-enabled=true, off only
                  # under %dev and %test), so the triple above is now the whole of what commissions
                  # it — no runner door and no per-run credential needs a line this file does not
                  # carry.
                  # QITS_DOMAIN REACHES THIS BLOCK TOO, through the SEED_DOMAIN fragment appended
                  # to the line below — every seed service gets it, not just this one
                  # (DomainTokens.seedDomain).
                  # IT IS NOT OPTIONAL FOR CI FROM qits-515 ON: the internal step-address plane
                  # (the qits-net aliases a step and a runner used to be handed directly) is gone,
                  # and every address a step or a runner is told now is the PUBLIC name qits-ci
                  # composes from this variable — ci.qits.<domain>, registry.qits.<domain>, and the
                  # rest (runnerhost/StepAddressPlane). A platform with no domain configured hands
                  # out no such address: qits-ci launches no step (LAUNCH_FAILED
                  # EDGE_PLANE_UNCONFIGURED on every run) and the runner register door answers 503.
                  # That is the CI-runners campaign's stated end state, not a regression to chase.
                  QITS_OBSERVABILITY_URL: http://${ENV_NAME}-qits-observability:8080${SEED_DOMAIN}
                # NO VOLUMES AT ALL, and there is nothing left to add. ci's /data held the H2 files,
                # and before that a bare git mirror per repository — it reads pipeline config off the
                # git host's content routes now. The daemon socket was the last mount and it is gone
                # with this cutover, so this container writes nothing that outlives it and holds
                # nothing that outranks it.
                networks: [qits-net]
                deploy:
                  replicas: 1
                  restart_policy:
                    condition: any
                    delay: 5s

              # THE CONTAINER ORCHESTRATOR. One service holds the docker socket and every module that
              # needs a workload asks it, instead of each one shelling `docker run` with a vocabulary
              # of its own. A row is what says a container may exist, which is what makes a restart
              # adopt what is already running rather than start a second copy of it.
              #
              # In the seed BECAUSE CI IS. qits-ci runs every pipeline step as a container it asks
              # this service for, and the first pipeline of this boot is minutes away — so the
              # orchestrator has to be up and healthy before it, not at its own place in the deploy
              # train. It is deployed there too, immediately before ci, so the two cutovers are
              # ordered rather than overlapping.
              #
              # An ENVIRONMENT service: one orchestrator per tier, holding the socket of the host that
              # tier runs on. The container name is this tier's alias, which is what its callers dial
              # and what the deployer searches for when it adopts this container's successor.
              ${ENV_NAME}-qits-containers:
                image: qits/containers:latest
                # Unprivileged uid stays; the socket group is all it needs — the same terms the
                # deployer holds it on, and the same spelling for the same reason: `group_add` is
                # not a stack-file key, so the group is the container's primary one and 1001 is the
                # image's own user. The deployed successor gets the group from the deployer, for its socket bind.
                user: "1001:${DOCKER_GID}"
                environment:
                  # TWO STORES, TWO TRIPLES, the same shape ci's and the git host's blocks carry: the
                  # registry of rows that says which containers may exist, and the outbox of the
                  # eventstream library, which is a second Flyway lineage and cannot share a database.
                  #
                  # SPELLED HERE, AND ONLY HERE: the seed stack starts this container before any deployer
                  # exists. Later deployments are handed the same six by qits-platform-deployments,
                  # from `resources: postgresql:db, postgresql:eventstream:qits_containers_eventstream`
                  # in this repository's deployments.yml — which is why the deployer's settings
                  # carry no datasource env either.
                  #
                  # It REFUSES TO BOOT without them, and for this service that is the failure worth
                  # having: the rows ARE the record of which containers may exist, so an orchestrator
                  # that came up on a store it invented would see every running container as claimed
                  # by no row.
                  QITS_RESOURCE_DB_URL: jdbc:postgresql://${ENV_NAME}-qits-oci-postgresql:5432/qits_containers
                  QITS_RESOURCE_DB_USERNAME: qits_containers
                  QITS_RESOURCE_DB_PASSWORD: "${PG_CONTAINERS_PASSWORD}"
                  QITS_RESOURCE_EVENTSTREAM_URL: jdbc:postgresql://${ENV_NAME}-qits-oci-postgresql:5432/qits_containers_eventstream
                  QITS_RESOURCE_EVENTSTREAM_USERNAME: qits_containers_eventstream
                  QITS_RESOURCE_EVENTSTREAM_PASSWORD: "${PG_CONTAINERS_EVENTSTREAM_PASSWORD}"
                  # The bus the outbox drains to, at its wire alias — bare since the bus moved to the
                  # platform plane, and stated rather than inherited from the jar's own default.
                  QITS_EVENTS_URL: http://${DIAL_EVENTS}:8080
                  # Machine auth, INBOUND ONLY, and EVERY route of this service is behind it —
                  # reads included, which is what makes it stricter than the rest of the platform: a
                  # row says which containers another module has running, and the owner in the path is
                  # the caller's own identity.
                  #
                  # NO AUDIENCE LINE: the image validates qits-platform out of its shipped
                  # quarkus.oidc.token.audience, the one name every minted token carries. See the
                  # deployer's block.
                  QITS_AUTH_MACHINE_REQUIRED: "${MACHINE_REQUIRED}"
                  QUARKUS_OIDC_AUTH_SERVER_URL: ${IDP_DIAL}
                  # ITS OWN IDP CLIENT, as the resource triple — see the edge's block. This service
                  # mints no token of its own, and the pair is still its own rather than borrowed:
                  # what it authenticates with it is the `docker pull` of every workload image, and
                  # a refused pull has to name the service that was refused.
                  QITS_RESOURCE_IDP_URL: ${IDP_DIAL}
                  QITS_RESOURCE_IDP_CLIENT_ID: ${ALIAS_CONTAINERS}
                  QITS_RESOURCE_IDP_CLIENT_SECRET: "${IDP_CLIENT_SECRET_CONTAINERS}"
                  # WHERE THE DOCKER CLI LOOKS FOR A CREDENTIAL, exactly as the deployer's block
                  # says: this container runs as uid 1001 with no home, so without this variable
                  # docker reads no config.json and every `docker pull` of a workload image is
                  # anonymous. The file on the volume below carries this service's own idp client,
                  # ${ENV_NAME}-qits-containers — the puller's identity, so a refusal names the
                  # service that was refused.
                  #
                  # LOAD-BEARING SINCE THE FLIP, and mounted before it for the same reason the
                  # deployer's was: gaining a credential must not be a redeploy of the one service
                  # that starts every workload on this host.
                  DOCKER_CONFIG: /work/config
                  QITS_OBSERVABILITY_URL: http://${ENV_NAME}-qits-observability:8080${SEED_DOMAIN}
                volumes:
                  # THE SOCKET. Starting containers is what this service is, so the mount is not a
                  # deployment's convenience but the whole component — and it is the one this
                  # platform means to concentrate: every module that holds it today asks this
                  # service instead, one at a time. The store is the postgres above, so nothing it
                  # writes outlives the container.
                  - /var/run/docker.sock:/var/run/docker.sock
                  # And the one file the docker CLI authenticates a pull with, which is why this
                  # volume holds no state of the service's own.
                  - qits-containers-config:/work/config
                networks: [qits-net]
                deploy:
                  replicas: 1
                  restart_policy:
                    condition: any
                    delay: 5s

              # THE TARGETS' OWNER, in the seed since 2026-10-23 (qits-1547) BECAUSE EVERY RUN IS A LEASE.
              # A CI run is one lease on a qits-system target since the CI step of epic qits-1481, so
              # the first release replay of a cold boot runs on this host's target or nowhere — and
              # the target registers with this service. It is deployed again at its own place in the
              # train, from its release run's image, like every seed service.
              #
              # The THIRD holder of the host's docker socket in this file, after the deployer and the
              # orchestrator, on the same terms: the base system panels read the daemon (`docker
              # info`, the swarm lists, this node's containers) and the admin console's terminals
              # exec into it. The power stays here rather than behind an endpoint on qits-containers.
              ${ENV_NAME}-qits-system:
                image: qits/system:latest
                # The socket group as the PRIMARY group, the orchestrator's spelling for the same
                # reason: `group_add` is not a stack-file key. The successor gets --group-add.
                user: "1001:${DOCKER_GID}"
                environment:
                  # TWO STORES, TWO TRIPLES — the targets module's rows (target, lease, work_volume)
                  # and the eventstream outbox it publishes TargetLeaseChanged through. SPELLED HERE,
                  # AND ONLY HERE: the seed stack starts this container before any deployer exists.
                  # Every deployment after this one is handed the same six by qits-deployments, from
                  # `resources: postgresql:db, postgresql:eventstream:qits_system_eventstream`.
                  QITS_RESOURCE_DB_URL: jdbc:postgresql://${ENV_NAME}-qits-oci-postgresql:5432/qits_system
                  QITS_RESOURCE_DB_USERNAME: qits_system
                  QITS_RESOURCE_DB_PASSWORD: "${PG_SYSTEM_PASSWORD}"
                  QITS_RESOURCE_EVENTSTREAM_URL: jdbc:postgresql://${ENV_NAME}-qits-oci-postgresql:5432/qits_system_eventstream
                  QITS_RESOURCE_EVENTSTREAM_USERNAME: qits_system_eventstream
                  QITS_RESOURCE_EVENTSTREAM_PASSWORD: "${PG_SYSTEM_EVENTSTREAM_PASSWORD}"
                  QITS_EVENTS_URL: http://${DIAL_EVENTS}:8080
                  QITS_AUTH_MACHINE_REQUIRED: "${MACHINE_REQUIRED}"
                  QUARKUS_OIDC_AUTH_SERVER_URL: ${IDP_DIAL}
                  # ITS OWN IDP CLIENT, as the resource triple. The targets module commissions every
                  # target's credentials with it (kinds target-runner and target-runner-registration),
                  # so without it the localhost target's create answers 503 and nothing runs.
                  QITS_RESOURCE_IDP_URL: ${IDP_DIAL}
                  QITS_RESOURCE_IDP_CLIENT_ID: ${ALIAS_SYSTEM}
                  QITS_RESOURCE_IDP_CLIENT_SECRET: "${IDP_CLIENT_SECRET_SYSTEM}"
                  # Where the docker CLI looks for its credential: the file on the volume below, the
                  # orchestrator's reason.
                  DOCKER_CONFIG: /work/config
                  QITS_SYSTEM_GLANCES_IMAGE_VERSION: 4.5.6-full
                  # QITS_DOMAIN (the SEED_DOMAIN fragment) is what the targets module composes every
                  # public address a target is told from — system.qits.<domain>, registry.qits.<domain>
                  # — and QITS_ENVIRONMENT is what it names the idp clients it commissions under.
                  QITS_OBSERVABILITY_URL: http://${ENV_NAME}-qits-observability:8080${SEED_DOMAIN}${TIER_ENV_SYSTEM}
                volumes:
                  - /var/run/docker.sock:/var/run/docker.sock
                  - qits-system-config:/work/config
                networks: [qits-net]
                deploy:
                  replicas: 1
                  restart_policy:
                    condition: any
                    delay: 5s

              # THE WORKSPACES' OWNER, in the seed since 2026-10-30 (qits-889). It starts every
              # regular workspace under a WORKSPACE lease on a qits-system target and admin ones
              # through qits-containers, from qits/workspace at the version it pins — which phase 1
              # built too, and tagged under the public registry name, so the localhost target finds
              # it without a pull. Every variable below is one the deployed container gets from
              # its image's defaults.
              ${ENV_NAME}-qits-workspaces:
                image: qits/workspaces:latest
                environment:
                  # TWO STORES, TWO TRIPLES, from `resources: postgresql:db,
                  # postgresql:eventstream:qits_workspaces_eventstream, idp:client`.
                  QITS_RESOURCE_DB_URL: jdbc:postgresql://${ENV_NAME}-qits-oci-postgresql:5432/qits_workspaces
                  QITS_RESOURCE_DB_USERNAME: qits_workspaces
                  QITS_RESOURCE_DB_PASSWORD: "${PG_WORKSPACES_PASSWORD}"
                  QITS_RESOURCE_EVENTSTREAM_URL: jdbc:postgresql://${ENV_NAME}-qits-oci-postgresql:5432/qits_workspaces_eventstream
                  QITS_RESOURCE_EVENTSTREAM_USERNAME: qits_workspaces_eventstream
                  QITS_RESOURCE_EVENTSTREAM_PASSWORD: "${PG_WORKSPACES_EVENTSTREAM_PASSWORD}"
                  QITS_CONTAINERS_URL: http://${ENV_NAME}-qits-containers:8080
                  # It REFUSES TO START without this one.
                  QITS_PROJECTS_URL: http://${ENV_NAME}-qits-projects:8080
                  QITS_GITHOST_URL: http://${ENV_NAME}-qits-githost:8080
                  QITS_WORKSPACE_CONTAINER_GIT_URL: http://githost.${ENV_NAME}.internal:8080
                  QITS_EVENTS_URL: http://${DIAL_EVENTS}:8080
                  # Its own name, for the daemons' control socket: `auto` is wrong in a container,
                  # silently.
                  QITS_WORKSPACE_GIT_HOST: ${ENV_NAME}-qits-workspaces
                  QITS_AUTH_MACHINE_REQUIRED: "${MACHINE_REQUIRED}"
                  QUARKUS_OIDC_AUTH_SERVER_URL: ${IDP_DIAL}
                  # ITS OWN IDP CLIENT, as the resource triple — its deployments.yml declares
                  # idp:client, and every peer call it makes carries a bearer minted from it.
                  QITS_RESOURCE_IDP_URL: ${IDP_DIAL}
                  QITS_RESOURCE_IDP_CLIENT_ID: ${ALIAS_WORKSPACES}
                  QITS_RESOURCE_IDP_CLIENT_SECRET: "${IDP_CLIENT_SECRET_WORKSPACES}"
                  # The tier line resolves its derived defaults (qits-system, qits-ci) to this
                  # platform's aliases, as it does on the deployed container.
                  QITS_OBSERVABILITY_URL: http://${ENV_NAME}-qits-observability:8080${SEED_DOMAIN}${TIER_ENV_WORKSPACES}
                # THE SAME DATA VOLUME THE DEPLOYED CONTAINER GETS (its `private:data:/data`), for
                # qits-projects' reason. The read-only agent-home archive its deployed container also
                # mounts is left off: qits-containers creates that volume, nothing in the seed
                # window resolves a session, and absent is a supported state of the reader.
                volumes:
                  - qits-workspaces-data:/data
                networks: [qits-net]
                deploy:
                  replicas: 1
                  restart_policy:
                    condition: any
                    delay: 5s

              # THE BUS, and last in this file because everything above publishes to it or subscribes to
              # it. In the seed since 2026-08-10, when ci's direct POST to the deployer was retired: a
              # green build now travels ci -> outbox -> here -> the deployer's durable subscriber, and
              # every hop of that chain has to exist before the FIRST deployment of a cold boot. The
              # pipeline deploys it too, at its ordinary place in the train — the seed is only what
              # carries the first six deployments, which used to announce into nothing.
              #
              # A PLATFORM service since 2026-08-17, so the key is the bare repository name and every tier
              # publishes and subscribes here. Scoping was never a topic — routing is event signature plus
              # a per-consumer watermark — so which broker a service dialled WAS the scope, and a platform
              # deployer on a per-tier bus could announce DeploymentActive to one tier only. The name below
              # is what the blocks above dial as QITS_EVENTS_URL and what the deployer searches for when
              # it adopts this container's successor at cutover.
              ${ALIAS_EVENTS}:
                image: qits/events:latest
                environment:
                  # SPELLED HERE, AND ONLY HERE, exactly as ci's and the idp's are:
                  # the seed stack starts this container before any deployer exists, so the bootstrap created
                  # the role and the database over JDBC and hands the credential over itself. Every
                  # deployment after this one is handed the same three by qits-platform-deployments, from
                  # `resources: postgresql:db` in this repository's deployments.yml — which is why the
                  # deployer's settings carry no datasource env either.
                  #
                  # The database name is the deployer's own default derivation, not a choice made here:
                  # the application name with `qits-` dropped, dashes underscored, under `qits_`. So the
                  # row the deployer registers on the first pipeline deployment is the row this creates.
                  #
                  # It REFUSES TO BOOT without them — the events jar's datasource is an expression over
                  # these three with no fallback URL — and for the bus that is the failure worth having:
                  # a bus that came up storing nothing would swallow every announcement silently.
                  QITS_RESOURCE_DB_URL: jdbc:postgresql://${ENV_NAME}-qits-oci-postgresql:5432/qits_events
                  QITS_RESOURCE_DB_USERNAME: qits_events
                  QITS_RESOURCE_DB_PASSWORD: "${PG_EVENTS_PASSWORD}"
                  QITS_OBSERVABILITY_URL: http://${ENV_NAME}-qits-observability:8080${SEED_DOMAIN}
                # No volume: the store is the postgres above, /data held the H2 and nothing else, and the
                # image has no mount point left for it.
                #
                # No machine auth: this service enforces none, so the deployed one is told none
                # either. Publishing to the bus is an ordinary PUT from qits-net.
                #
                # Both names, for the reason spelled on qits-idp's block above.
                ${SEED_NETWORKS_EVENTS}
                deploy:
                  replicas: 1
                  restart_policy:
                    condition: any
                    delay: 5s
            """;
}
